import re

_ENTRY_RE = re.compile(r"^(\d{4}-\d{2}-\d{2}) (\d{2}:\d{2})-(\d{2}:\d{2}) (.+)$")


def _minutes(hhmm: str) -> int:
    try:
        hours, mins = hhmm.split(":")
        h, m = int(hours), int(mins)
    except (ValueError, AttributeError):
        raise ValueError(f"invalid time: {hhmm!r}") from None
    if not (0 <= h <= 23 and 0 <= m <= 59):
        raise ValueError(f"time out of range: {hhmm!r}")
    return h * 60 + m


def parse_entry(line: str) -> dict:
    """Parse a timesheet line into date, start, end, minutes and task."""
    match = _ENTRY_RE.match(line.strip())
    if not match:
        raise ValueError(f"malformed entry: {line!r}")
    date, start, end, task = match.groups()
    start_m = _minutes(start)
    end_m = _minutes(end)
    if end_m <= start_m:
        raise ValueError(f"end not after start: {line!r}")
    task = task.strip()
    if not task:
        raise ValueError(f"empty task: {line!r}")
    return {"date": date, "start": start, "end": end, "minutes": end_m - start_m, "task": task}

